// Turn Meta's WhatsApp event into a simple message
return $input.all().map(item => {
  const v = item.json.body?.entry?.[0]?.changes?.[0]?.value
         ?? item.json.entry?.[0]?.changes?.[0]?.value
         ?? item.json;
  const msg = v.messages?.[0];
  const contact = v.contacts?.[0] ?? {};
  if (!msg) return { json: { is_message: false } }; // delivery/read receipts

  let text = '';
  if (msg.type === 'text') text = msg.text?.body ?? '';
  else if (msg.type === 'button') text = msg.button?.text ?? '';
  else if (msg.type === 'interactive')
    text = msg.interactive?.button_reply?.title ?? msg.interactive?.list_reply?.title ?? '';
  else text = `[${msg.type} message]`;

  return { json: {
    is_message: true,
    phone: String(msg.from || contact.wa_id || '').replace(/\D/g, ''),
    text: String(text).trim(),
    wa_message_id: msg.id,
    received_at: new Date(Number(msg.timestamp) * 1000).toISOString()
  }};
});

const ai = $('Lead setter').first().json.output;
const before = $('Save or update lead').first().json.status;
const lead = $input.first().json;
const name = lead.first_name ? `, ${lead.first_name}` : '';

// Already booked: remove any sentence asking her to book or containing the booking link
if (lead.status === 'booked') {
  const bookingNudge = /[^.!?]*(\bwhen you book\b|\bonce you('ve| have)? booked\b|\bbook (a|your) (call|slot|time)\b|cal\.com\S*)[^.!?]*[.!?]?\s*/gi;
  let reply = ai.replace(bookingNudge, '').trim();
  if (!reply) reply = `You're all booked in${name} 😊 Claire's looking forward to chatting with you.`;
  return [{ json: { reply } }];
}

if (lead.status !== 'handoff') return [{ json: { reply: ai } }];
if (/samaritans|116 123|\b999\b/i.test(ai)) return [{ json: { reply: ai } }];

const reply = before === 'handoff'
  ? `Thanks${name}. Claire has your messages and will reply to you here within 1 working day.`
  : `Thank you for telling me${name}. That's one for Claire herself, so I've passed your message to her. She'll reply to you here within 1 working day.`;
return [{ json: { reply } }];

// Spot GDPR commands before the AI sees the message
const text = $('Read message').first().json.text.toLowerCase().trim();
let command = 'none';
if (/\bdelete (all )?(my )?(data|details|information)\b/.test(text)) command = 'delete';
else if (/^(stop|unsubscribe|opt out|not interested)[.!]*$/.test(text)) command = 'stop';
return [{ json: { ...$input.first().json, command } }];
